CREATE TEMP TABLE response AS
SELECT http_get('https://example.com/') AS r;
SELECT (r->>'status')::INTEGER AS status,
       r->>'reason' AS reason,
       r->>'body' AS body
FROM response;

WITH r AS (
  SELECT '{"status":200,
    "body":"{\"count\":42}"}'::JSON AS v
)
SELECT ((v->>'body')::JSON)->>'count' AS n
FROM r;
